from fractions import Fraction

def random_graph(n):
    edges = set()
    for i in range(n):
        for j in range(i+1, n):
            if random.choice([True, False]):
                edges.add((i, j))
    return edges

def adjacency_matrix(graph, n):
    matrix = [[0] * n for _ in range(n)]
    for u, v in graph:
        matrix[u][v] = 1
        matrix[v][u] = 1
    return matrix

def gaussian_elimination(matrix):
    n = len(matrix)
    for i in range(n):
        max_row = i
        for j in range(i+1, n):
            if abs(matrix[j][i]) > abs(matrix[max_row][i]):
                max_row = j
        matrix[i], matrix[max_row] = matrix[max_row], matrix[i]
        if matrix[i][i] == 0:
            raise ValueError("Matrix is singular")
        for j in range(i+1, n):
            factor = Fraction(matrix[j][i], matrix[i][i])
            for k in range(i, n):
                matrix[j][k] -= factor * matrix[i][k]
    return matrix

def determinant(matrix):
    if len(matrix) != len(matrix[0]):
        raise ValueError("Matrix must be square")
    n = len(matrix)
    det = Fraction(1)
    for i in range(n):
        det *= matrix[i][i]
    return det

def min_tropical_rank(matrix):
    n = len(matrix)
    identity = [[Fraction(1) if i == j else Fraction(0) for j in range(n)] for i in range(n)]
    augmented_matrix = [row + col for row, col in zip(matrix, identity)]
    gaussian_eliminated = gaussian_elimination(augmented_matrix)
    min_tr = sum(1 for row in gaussian_eliminated if any(x != 0 for x in row))
    return min_tr

def circuit_size(graph):
    n = len(graph)
    edges = list(graph)
    vertices = set(range(n))
    visited = [False] * n
    stack = []

    def dfs(v):
        visited[v] = True
        stack.append(v)
        for u in range(n):
            if (v, u) in edges or (u, v) in edges:
                if not visited[u]:
                    dfs(u)
        stack.pop()

    connected_components = 0
    for v in vertices:
        if not visited[v]:
            connected_components += 1
            dfs(v)

    return len(edges) + connected_components - 1

